package com.olgun.qr;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.provider.MediaStore;import android.content.ContentValues;import android.view.*;import android.widget.*;import java.io.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;import com.google.zxing.EncodeHintType;import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel;import java.util.*;
public class MainActivity extends Activity {
 EditText input;ImageView preview;Spinner sizes;Bitmap qr,logo;TextView status;
 int[] px={256,512,1024,2048};int PICK=12;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.WHITE);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
 ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Color.WHITE);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,28,22,24);scroll.addView(root);setContentView(scroll);
 TextView title=new TextView(this);title.setText("▦  QR");title.setTextSize(30);title.setTextColor(Color.BLACK);title.setTypeface(null,1);root.addView(title);
 TextView sub=new TextView(this);sub.setText("Mobil QR Kod Oluşturucu");sub.setTextColor(Color.DKGRAY);root.addView(sub);
 heading(root,"01 · Metin veya URL");input=new EditText(this);input.setHint("Metin veya bağlantı giriniz...");input.setMinLines(3);input.setGravity(Gravity.TOP);input.setTextColor(Color.BLACK);input.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.DKGRAY));root.addView(input);input.setText(getPreferences(0).getString("text",""));
 button(root,"QR KOD OLUŞTUR",()->generate(false));
 heading(root,"02 · Logo (isteğe bağlı)");button(root,"LOGO SEÇ",()->{Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("image/*");startActivityForResult(i,PICK);});button(root,"LOGOYU KALDIR",()->{logo=null;message("Logo kaldırıldı");});
 heading(root,"03 · QR Önizleme");preview=new ImageView(this);preview.setBackgroundColor(Color.WHITE);preview.setMinimumHeight(280);preview.setAdjustViewBounds(true);root.addView(preview);
 sizes=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"256 × 256","512 × 512","1024 × 1024","2048 × 2048"});sizes.setAdapter(adapter);sizes.setSelection(1);root.addView(sizes);
 button(root,"PNG OLARAK KAYDET",()->generate(true));button(root,"METNİ KOPYALA",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("QR",input.getText().toString()));message("Metin kopyalandı");});
 button(root,"FORMU TEMİZLE",()->{input.setText("");preview.setImageDrawable(null);getPreferences(0).edit().remove("text").apply();});
 status=new TextView(this);status.setTextColor(Color.DKGRAY);status.setPadding(0,16,0,10);root.addView(status);
 TextView foot=new TextView(this);foot.setText("QR · Mobil UI\nDesigner: Muhammed Yusuf OLGUN");foot.setTextColor(Color.GRAY);foot.setGravity(Gravity.CENTER);root.addView(foot);
 }
 void heading(LinearLayout r,String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(17);t.setTypeface(null,1);t.setTextColor(Color.BLACK);t.setPadding(0,26,0,10);r.addView(t);}
 void button(LinearLayout r,String s,Runnable run){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.BLACK));r.addView(b);b.setOnClickListener(v->run.run());}
 void message(String s){status.setText(s);}
 void generate(boolean save){String s=input.getText().toString();if(s.trim().isEmpty()){message("Metin veya URL giriniz");return;}getPreferences(0).edit().putString("text",s).apply();try{int n=px[sizes.getSelectedItemPosition()];Map<EncodeHintType,Object> opts=new HashMap<>();opts.put(EncodeHintType.ERROR_CORRECTION,ErrorCorrectionLevel.H);opts.put(EncodeHintType.MARGIN,2);BitMatrix m=new QRCodeWriter().encode(s,BarcodeFormat.QR_CODE,n,n,opts);qr=Bitmap.createBitmap(n,n,Bitmap.Config.ARGB_8888);for(int y=0;y<n;y++)for(int x=0;x<n;x++)qr.setPixel(x,y,m.get(x,y)?Color.BLACK:Color.WHITE);if(logo!=null){Canvas c=new Canvas(qr);int z=n/5;Bitmap l=Bitmap.createScaledBitmap(logo,z,z,true);Paint p=new Paint(3);c.drawRect((n-z)/2-6,(n-z)/2-6,(n+z)/2+6,(n+z)/2+6,white());c.drawBitmap(l,(n-z)/2,(n-z)/2,p);}preview.setImageBitmap(qr);if(save){ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"QR_"+System.currentTimeMillis()+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/QR");Uri u=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(u==null)throw new IOException("Dosya açılamadı");try(OutputStream out=getContentResolver().openOutputStream(u)){if(!qr.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("PNG yazılamadı");}message("PNG kaydedildi: Resimler/QR");}else message("QR kod oluşturuldu");}catch(Exception e){message("Hata: "+e.getMessage());}}
 Paint white(){Paint p=new Paint();p.setColor(Color.WHITE);return p;}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK&&result==RESULT_OK&&data!=null){try(InputStream in=getContentResolver().openInputStream(data.getData())){logo=BitmapFactory.decodeStream(in);message("Logo seçildi");}catch(Exception e){message("Logo açılamadı");}}}
}